<?php
require __DIR__.'/includes/bootstrap.php'; require_login();
$type=$_GET['type']??'all'; $category=trim((string)($_GET['category']??'')); $month=$_GET['month']??budget_cycle_key(); [$start,$end,$month]=budget_cycle_bounds($month);
$sql="SELECT t.*,tm.source,tm.bucket,tm.income_kind,tm.financial_month,m.name creator_name FROM transactions t LEFT JOIN transaction_meta tm ON tm.transaction_id=t.id LEFT JOIN family_members m ON m.id=t.created_by_member_id WHERE ";$params=[];
if($type==='income'){$sql.="t.type='income' AND t.transaction_date BETWEEN ? AND ?";$params=[$start,$end];}
elseif($type==='expense'){$sql.="t.type='expense' AND t.transaction_date BETWEEN ? AND ?";$params=[$start,$end];}
else{$sql.="t.transaction_date BETWEEN ? AND ?";$params=[$start,$end];}
if($category!==''){ $sql.=' AND t.category=?'; $params[]=$category; }
$sql.=' ORDER BY t.transaction_date DESC,t.id DESC'; $s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
$pageTitle='Tranzacții';$active='money';require __DIR__.'/includes/layout_top.php';
?>
<div class="filter-period-label"><small>Interval bugetar</small><strong><?=e(budget_cycle_label($month))?></strong></div><form class="filters" method="get"><input type="month" name="month" value="<?=e($month)?>"><select name="type"><option value="all" <?=$type==='all'?'selected':''?>>Toate</option><option value="expense" <?=$type==='expense'?'selected':''?>>Cheltuieli</option><option value="income" <?=$type==='income'?'selected':''?>>Încasări</option></select><?php if($category!==''):?><input type="hidden" name="category" value="<?=e($category)?>"><?php endif;?><button class="btn soft">Filtrează</button><?php if($category!==''):?><a class="btn ghost" href="/transactions.php?month=<?=e($month)?>&type=<?=e($type)?>">Toate categoriile</a><?php endif;?></form><?php if($category!==''):?><div class="filter-chip-row"><span class="status">Categorie: <?=e($category)?></span></div><?php endif;?>
<div class="tx-list spaced"><?php if(!$rows):?><div class="empty">Nu există tranzacții pentru perioada selectată.</div><?php endif;?><?php foreach($rows as $t):?><article class="tx-row"><div class="tx-icon <?=$t['type']?>"><?=icon($t['type']==='income'?'income':'expense')?></div><div class="tx-main"><strong><?=e($t['name'])?></strong><span><?=e($t['category']?:'Fără categorie')?> · <?=e(tx_date_ro($t['transaction_date']))?><?php if(!empty($t['creator_name'])):?> · <?=e($t['creator_name'])?><?php endif;?><?php $sourceLabel=finance_source_label($t['source']??''); if($t['type']==='income'&&!empty($t['income_kind'])&&isset(income_kind_labels()[$t['income_kind']])):?> · <?=e(income_kind_labels()[$t['income_kind']])?><?php endif;?><?php if($sourceLabel):?> · <?=e($sourceLabel)?><?php elseif($t['type']==='expense'&&$t['bucket']==='fixed'):?> · Fix<?php endif;?></span></div><div class="tx-side"><strong class="<?=$t['type']==='income'?'pos':'neg'?>"><?=$t['type']==='income'?'+':'−'?><?=money_ro($t['amount'])?></strong><button class="link danger" data-delete-tx="<?=$t['id']?>">Șterge</button></div></article><?php endforeach;?></div>
<?php require __DIR__.'/includes/layout_bottom.php'; ?>
